## boxplots of pseudobulk expression per Group-Time for a set of genes
boxplot_Group_Time <- function(seu_target, mat, target_gl, ncol = 4, hide_ns = TRUE){
    ## sample annotation joined from metadata (robust to column-name separators)
    annotation_col <- seu_target@meta.data %>%
        dplyr::distinct(target, Time, Group, Mouse) %>%
        dplyr::mutate(Group = factor(Group, levels = c('SPF','GF')))
    mat_plot <- mat[target_gl,] %>%
        t() %>%
        as.data.frame() %>%
        tibble::rownames_to_column('target') %>%
        dplyr::left_join(annotation_col, by = 'target') %>%
        tidyr::pivot_longer(cols = tidyselect::all_of(target_gl),
                            names_to = 'gene', values_to = 'expression')
    plot_list <- list()
    for (i in target_gl){
        plot_list[[i]] <- mat_plot %>%
            mutate(Group_Time = paste(Group, Time, sep='-')) %>%
            dplyr::filter(gene == i) %>%
            ggplot(aes(Group_Time, expression, fill = Group_Time)) +
            geom_boxplot(outlier.shape = NA, coef = 0, size = 0.1) +
            scale_fill_manual(values = Group_Time.color) +
            geom_jitter(color = '#4B4453', shape = 19, size = 0.2, width = 0.2, height = 0.1) +
            labs(title = i) +
            ggpubr::stat_compare_means(aes(group = Group_Time), label = "p.signif",
                                       method = "t.test", vjust = 1.5,
                                       hide.ns = hide_ns, comparisons = Group_Time_comp) +
            xlab('') + ylab('') + theme_classic() +
            theme(axis.text.x = element_blank(),
                  plot.title = element_text(face = "italic"),
                  legend.position = 'none',
                  panel.background = element_blank(), plot.background = element_blank())
    }
    wrap_plots(plot_list, ncol = ncol)
}

## DEG filtering cutoffs
LFC.cutoff <- 0.5
FDR.cutoff <- 0.05
baseMean.cutoff <- 5

## SPF/GF upregulated genes from a DEG table (rownames = genes), bad features removed
spf_up <- function(deg){
    deg %>% filter(log2FoldChange >= LFC.cutoff & padj <= FDR.cutoff & baseMean >= baseMean.cutoff) %>%
        rownames() %>% rm.bad.features()
}
gf_up <- function(deg){
    deg %>% filter(log2FoldChange <= -LFC.cutoff & padj <= FDR.cutoff & baseMean >= baseMean.cutoff) %>%
        rownames() %>% rm.bad.features()
}

## volcano plot of merged DEG tables (one facet per time point)
add_sign <- function(data, time_label){
    data %>%
        mutate(Time = time_label) %>%
        filter(!is.na(padj)) %>%
        tibble::rownames_to_column(var = 'Gene') %>%
        filter(Gene %in% good_features) %>%
        mutate(sign = ifelse((log2FoldChange > LFC.cutoff) & (padj <= FDR.cutoff), 'SPF',
                      ifelse((log2FoldChange < -LFC.cutoff) & (padj <= FDR.cutoff), 'GF', 'NS')))
}
plot_volcano <- function(deg, out_pdf, max.overlaps = 15){
    p <- ggplot() +
        geom_point(data = deg %>% filter(sign == 'NS'), aes(log2FoldChange, -log10(padj)),
                   shape = 19, size = 0.2, color = 'grey') +
        geom_point(data = deg %>% filter(sign == 'SPF'), aes(log2FoldChange, -log10(padj)),
                   shape = 19, size = 0.4, color = '#EBBE35') +
        geom_text_repel(data = deg %>% filter(sign == 'SPF'),
                        aes(log2FoldChange, -log10(padj), label = Gene), size = 4, max.overlaps = max.overlaps) +
        geom_point(data = deg %>% filter(sign == 'GF'), aes(log2FoldChange, -log10(padj)),
                   shape = 19, size = 0.4, color = '#7CCAE4') +
        geom_text_repel(data = deg %>% filter(sign == 'GF'),
                        aes(log2FoldChange, -log10(padj), label = Gene), size = 4, max.overlaps = max.overlaps) +
        facet_wrap(~Time) + xlab('Log2FoldChange') + ylab('-log10(adjusted P)') +
        theme(strip.text = element_text(size = 16))
    ggsave(out_pdf, plot = p, width = 8, height = 5)
}

