#################################################################
## Data preparation: filter samples by minimal cell number (cutoff 10/15/20)
## for Mon, Neu and Mac; the cutoff15 cell lists are used in Figure3.py
#################################################################
filter_cutoff_cells <- function(seu_target, out_rds){
    cell_list <- list()
    for (i in c(10, 15, 20)){
        min.cell.num.cutoff <- i
        target_cutoff <- data.frame(table(seu_target$target)) %>%
            dplyr::rename(target = Var1) %>%
            tidyr::separate(col = 'target', into = c('Time','Tissue','Group','Mouse'), sep = ' ') %>%
            dplyr::mutate(Group = factor(Group, levels = c('SPF','GF'))) %>%
            filter(Freq >= min.cell.num.cutoff) %>%
            mutate(target = paste(Time, Tissue, Group, Mouse, sep = ' ')) %>%
            pull(target)
        message('Cutoff ', i, ' | cells kept: ', sum(seu_target$target %in% target_cutoff),
                ' / ', ncol(seu_target))
        seu_target_filt <- subset(seu_target, target %in% target_cutoff)
        cell_list[[sprintf('cutoff%s', i)]] <- colnames(seu_target_filt)
    }
    saveRDS(cell_list, out_rds)
    return(cell_list)
}

