## Fig. 3d, GO enrichment of SPF-upregulated DEGs in monocytes
#################################################################
## background: all genes detected by the MARS-Seq pipeline (exported in Figure3.py)
gene_list <- read.csv('mye/data/Mouse_54542g.csv', row.names = 1)

ego_write <- function(gl,                       # genes to enrich
                      database = org.Mm.eg.db,  # species
                      backgroud = gene_list$Symbol, # background
                      range = "ALL",            # GO sub-ontology
                      path = 'mye/output/GOanalysis/', # save path
                      name = 'Mon_P16_SPF'      # save prefix
                      ){
    ego <- enrichGO(gene = gl,
                    keyType = 'SYMBOL',
                    universe = backgroud,
                    OrgDb = database,
                    ont = range,
                    pAdjustMethod = "BH",
                    pvalueCutoff = 0.01,
                    qvalueCutoff = 0.05,
                    readable = TRUE)
    write.csv(ego@result, paste0(path, 'GO_res_', name, '.csv'))
}

