## half-violin plot per cell lineage
plot_ag_violin <- function(cells, tissues_excluded, out_pdf, width){
    p <- seu@meta.data[rownames(seu@meta.data) %in% cells,] %>%
        filter(!Tissue_mod_only %in% tissues_excluded) %>%
        mutate(Tissue_mod_only = recode(Tissue_mod_only, !!!tis_change)) %>%
        dplyr::mutate(Tissue_mod_only = factor(Tissue_mod_only,
                      levels = c('SP','SI','CL','LV','LU','KD','HT','SK','TM','BM'))) %>%
        ggplot(aes(paste0(Time, '_', Group), ag_proc_pres1, color = Group)) +
        geom_jitter(aes(fill = Group), shape = 19, size = 0.1, width = 0.1) +
        geom_half_violin(position = position_nudge(x = 0.2), side = "r", scale = 'area', width = 1) +
        scale_color_manual(values = Group.color) +
        scale_fill_manual(values = Group.color) +
        ggsignif::geom_signif(comparisons = list(c('P16_GF','P16_SPF'),
                                                 c('W4_GF','W4_SPF'),
                                                 c('W9_GF','W9_SPF')),
                              test = t.test, map_signif_level = FALSE,
                              step_increase = 0.15, textsize = 3) +
        facet_wrap(~Tissue_mod_only, nrow = 1) +
        theme_classic() +
        theme(axis.text.x = element_blank(), legend.position = 'none',
              strip.text = element_text(size = 20)) +
        xlab('') + ylab('')
    ggsave(out_pdf, plot = p, width = width, height = 4)
}

