## helper functions for DEG tables written by read.csv (first column = X)
get_SPF <- function(deg_table){
    deg_table %>%
        dplyr::rename(gene = X) %>%
        filter(gene %in% good_features) %>%
        filter(log2FoldChange >= LFC.cutoff & padj <= FDR.cutoff & baseMean >= baseMean.cutoff) %>%
        pull(gene)
}
get_GF <- function(deg_table){
    deg_table %>%
        dplyr::rename(gene = X) %>%
        filter(gene %in% good_features) %>%
        filter(log2FoldChange <= -LFC.cutoff & padj <= FDR.cutoff & baseMean >= baseMean.cutoff) %>%
        pull(gene)
}

## 8 subsets with sufficient replicates, DEGs called per time point
baseMean.cutoff <- 1
time_list <- c('P16','W4','W9')
celltype_list <- c('Basophil', 'cDC1', 'cDC2_Ms4a4c', 'Mac_Il1b',
                   'Mon', 'Mon_bm', 'Neu_bm_Ccl6(Neg)', 'pDC')
deg_count <- data.frame(Cluster = character(), Time = character(),
                        Group = character(), Num = numeric(), Gene = I(list()))
for (celltype in celltype_list){
    for (time in time_list){
        target <- read.csv(sprintf('mye/output/scanpy/decoupler/%s_%s_pseudobulk_deg_downsample300.csv', celltype, time))
        spf_genes <- get_SPF(target)
        gf_genes <- get_GF(target)
        deg_count <- rbind(deg_count,
                           data.frame(Cluster = celltype, Time = time, Group = 'SPF',
                                      Num = length(spf_genes), Gene = I(list(spf_genes))),
                           data.frame(Cluster = celltype, Time = time, Group = 'GF',
                                      Num = length(gf_genes), Gene = I(list(gf_genes))))
    }
}

p <- deg_count %>%
    ggplot(aes(Time, Num, fill = Group)) +
    geom_bar(stat = 'identity', position = 'dodge') +
    scale_fill_manual(values = c('SPF'='#EBBE35','GF'='#7CCAE4')) +
    geom_text(aes(label = ifelse(Num > 0, Num, "")), position = position_dodge(width = 0.9), vjust = -0.3) +
    facet_wrap(~Cluster, nrow = 2)
