## scatter of DESeq2 Wald statistics per subset and time point
deg_total <- data.frame()
for (celltype in celltype_list){
    for (time in time_list){
        target <- read.csv(sprintf('mye/output/scanpy/decoupler/%s_%s_pseudobulk_deg_downsample300.csv', celltype, time)) %>%
            dplyr::rename(gene = X) %>%
            mutate(Cluster = celltype, Time = time)
        deg_total <- rbind(deg_total, target)
    }
}
deg_total <- deg_total %>%
    filter(!is.na(padj)) %>%
    mutate(sig = if_else((log2FoldChange >= LFC.cutoff) & (padj <= FDR.cutoff) & (baseMean >= baseMean.cutoff) & (gene %in% good_features), 'SPF',
                  if_else((log2FoldChange <= -LFC.cutoff) & (padj <= FDR.cutoff) & (baseMean >= baseMean.cutoff) & (gene %in% good_features), 'GF', 'NS')))

property <- data.frame(celltype = rep(celltype_list, each = 3), time = rep(time_list, 8)) %>%
    mutate(sample = paste0(celltype, '_', time))
celltype_bar <- ggplot(property, aes(sample, 1, fill = celltype)) +
    geom_tile() + scale_fill_manual(values = col.24) + theme_void()
time_bar <- ggplot(property, aes(sample, 1, fill = time)) +
    geom_tile() + scale_fill_manual(values = c('P16'='#F3C5FF','W4'='#9B89B3','W9'='#845EC2')) + theme_void()

deg_point <- deg_total %>%
    ggplot(aes(paste0(Cluster, '_', Time), stat, color = sig)) +
    geom_jitter(shape = 19, size = 1) +
    scale_color_manual(values = c('SPF'='#EBBE35','GF'='#7CCAE4','NS'='grey')) +
    geom_text_repel(data = deg_total %>% filter(sig == 'SPF'),
                    aes(x = paste0(Cluster, '_', Time), y = stat, label = gene), size = 4, max.overlaps = 5) +
    geom_text_repel(data = deg_total %>% filter(sig == 'GF'),
                    aes(x = paste0(Cluster, '_', Time), y = stat, label = gene), size = 4, max.overlaps = 5) +
    xlab('') + theme(axis.title.y = element_text(size = 8), axis.text.x = element_blank())

p <- deg_point %>%
    insert_top(time_bar, height = 0.1) %>%
    insert_top(celltype_bar, height = 0.1)
ggsave('mye/figures/Batch_deg.pdf', plot = p, width = 10, height = 6)

