annotation_col <- data.frame(target = colnames(mat), index = 1:NCOL(mat)) %>%
    tidyr::separate(col = 'target', into = c('Time','Tissue','Group','Mouse'), sep = ' ') %>%
    mutate(Tissue = recode(Tissue, !!!tis_change)) %>%
    dplyr::mutate(Tissue = factor(Tissue, levels = c('BM','SP','SI','CL','LV','LU','HT','KD','SK','TM'))) %>%
    dplyr::mutate(Group = factor(Group, levels = c('GF','SPF'))) %>%
    dplyr::arrange(Tissue, Group, Time, Mouse)

top_anno <- columnAnnotation(
    Group = annotation_col$Group,
    Time = annotation_col$Time,
    col = list(Group = Group.color, Time = Time.color))

## SPF-upregulated DEGs
mat_plot <- as.matrix(mat[spf.degs, colnames(mat)[annotation_col$index]])
p <- Heatmap(mat_plot,
             col = circlize::colorRamp2(c(-2, 0, 2), c('blue','white','red')),
             name = " ",
             cluster_rows = TRUE,
             cluster_columns = FALSE,
             show_column_names = FALSE,
             show_row_names = TRUE,
             row_names_gp = gpar(fontsize = 8, fontface = "italic"),
             top_annotation = top_anno,
             column_split = annotation_col$Tissue,
             column_names_gp = gpar(fontsize = 10),
             column_title_gp = gpar(fontsize = 18),
             column_title_rot = 0)
pdf('mye/figures/Heatmap/Neu_spf_heatmap.pdf', width = 10, height = 3)
print(p)
dev.off()

## GF-upregulated DEGs
mat_plot <- as.matrix(mat[gf.degs, colnames(mat)[annotation_col$index]])
p <- Heatmap(mat_plot,
             col = circlize::colorRamp2(c(-2, 0, 2), c('blue','white','red')),
             name = " ",
             cluster_rows = TRUE,
             cluster_columns = FALSE,
             show_column_names = FALSE,
             show_row_names = TRUE,
             row_names_gp = gpar(fontsize = 8, fontface = "italic"),
             top_annotation = top_anno,
             column_split = annotation_col$Tissue,
             column_names_gp = gpar(fontsize = 10),
             column_title_gp = gpar(fontsize = 18),
             column_title_rot = 0)
pdf('mye/figures/Heatmap/Neu_gf_heatmap.pdf', width = 10, height = 2)
print(p)
dev.off()

